// Ported from the Node app's Sequelize model Payslip (first generated by tools/gen-efcore.mjs).
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SchoolERP.Domain.Entities;

namespace SchoolERP.Infrastructure.Persistence.Configurations;

internal sealed class PayslipConfiguration : IEntityTypeConfiguration<Payslip>
{
    public void Configure(EntityTypeBuilder<Payslip> builder)
    {
        builder.ToTable("payslips", t =>
        {
            t.HasCheckConstraint("CK_payslips_status", "[status] IN (N'draft', N'paid')");
        });
        builder.ConfigureAudit();
        builder.HasQueryFilter(e => !e.Delstatus);
        builder.HasKey(e => e.Id);
        builder.Property(e => e.Id).HasColumnName("id").UseIdentityColumn();
        builder.Property(e => e.StaffId).HasColumnName("staff_id");
        builder.Property(e => e.Month).HasColumnName("month").HasColumnType("nvarchar(7)").HasMaxLength(7).IsRequired();
        builder.Property(e => e.Basic).HasColumnName("basic").HasColumnType("decimal(10,2)");
        builder.Property(e => e.Allowances).HasColumnName("allowances").HasColumnType("decimal(10,2)").HasDefaultValueSql("0");
        builder.Property(e => e.Deductions).HasColumnName("deductions").HasColumnType("decimal(10,2)").HasDefaultValueSql("0");
        builder.Property(e => e.Net).HasColumnName("net").HasColumnType("decimal(10,2)");
        builder.Property(e => e.Status).HasColumnName("status").HasColumnType("nvarchar(20)").IsRequired().HasDefaultValueSql("N'draft'");
        builder.Property(e => e.PaidOn).HasColumnName("paid_on").HasColumnType("date");
        builder.Property(e => e.PaidByName).HasColumnName("paid_by_name").HasColumnType("nvarchar(100)").HasMaxLength(100);
        builder.HasIndex(e => new { e.StaffId, e.Month }).IsUnique().HasDatabaseName("uq_payslip");
        builder.HasOne(e => e.Staff).WithMany(p => p.Payslips).HasForeignKey(e => e.StaffId).OnDelete(DeleteBehavior.NoAction);
    }
}
